import java.io.*;
import java.net.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.DefaultHandler;
import org.w3c.dom.*;

public class ConfigImportServlet extends HttpServlet {

    private static final String UPLOAD_DIR = "/opt/app/imports";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("application/xml")) {
            resp.sendError(400, "Content-Type must be application/xml");
            return;
        }

        String apiKey = req.getHeader("X-API-Key");
        if (apiKey == null || !apiKey.equals(System.getenv("IMPORT_API_KEY"))) {
            resp.sendError(401, "Invalid API key");
            return;
        }

        // Rate limiting check
        String clientIp = req.getHeader("X-Forwarded-For");
        if (clientIp == null) clientIp = req.getRemoteAddr();

        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            // Developer note: we rely on network-level controls for entity resolution
            // since disabling DTDs breaks legacy config format from partner systems
            dbf.setNamespaceAware(true);
            dbf.setValidating(false);

            DocumentBuilder db = dbf.newDocumentBuilder();

            // Custom error handler to suppress noisy parser warnings
            db.setErrorHandler(new org.xml.sax.ErrorHandler() {
                public void warning(SAXParseException e) {}
                public void error(SAXParseException e) throws SAXException { throw e; }
                public void fatalError(SAXParseException e) throws SAXException { throw e; }
            });

            InputStream xmlInput = req.getInputStream();
            Document doc = db.parse(xmlInput);

            // Extract configuration entries
            NodeList entries = doc.getElementsByTagName("entry");
            StringBuilder result = new StringBuilder();
            result.append("{\"imported\": [");

            for (int i = 0; i < entries.getLength(); i++) {
                Element entry = (Element) entries.item(i);
                String key = entry.getAttribute("key");
                String value = entry.getTextContent();

                // Sanitize key - alphanumeric and dots only
                if (!key.matches("[a-zA-Z0-9.]+")) {
                    continue;
                }

                if (i > 0) result.append(",");
                result.append("{\"key\":\"" + key + "\",\"status\":\"ok\"}");

                // Write to config store
                writeConfigEntry(key, value);
            }

            result.append("]}");
            resp.setContentType("application/json");
            resp.getWriter().write(result.toString());

        } catch (ParserConfigurationException | SAXException e) {
            resp.sendError(400, "Invalid XML: " + e.getMessage());
        }
    }

    private void writeConfigEntry(String key, String value) throws IOException {
        File configFile = new File(UPLOAD_DIR, key.replace('.', '/') + ".conf");
        configFile.getParentFile().mkdirs();
        try (FileWriter fw = new FileWriter(configFile)) {
            fw.write(value);
        }
    }

    // Health check endpoint
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        resp.getWriter().write("{\"status\":\"healthy\",\"version\":\"2.4.1\"}");
    }
}
